import{_ as l,B as n,c as d,o as i,j as o,at as v,t as a,F as u,C as h,G as c,w as m,a as p}from"./chunks/framework.BlwsHpGA.js";const g="/img/frog-profile.svg",f="/img/frog-ui-main.png",_="/img/be-ui-vue.svg",k="/img/beui_vue_screenshot.png",I=JSON.parse('{"title":"각자가 가야할 길 - 분리","description":"스타일과 기능을 분리해 디자인 시스템과 headless UI 구조를 설계","frontmatter":{"layout":"doc","title":"각자가 가야할 길 - 분리","description":"스타일과 기능을 분리해 디자인 시스템과 headless UI 구조를 설계","lastUpdated":true,"editLink":true,"navbar":true,"sidebar":true,"aside":true,"outline":"deep"},"headers":[],"relativePath":"beui/journey3.md","filePath":"beui/journey3.md"}'),q={name:"beui/journey3.md"},y=Object.assign(q,{setup(P){const b=["vue3","composition api","css","scss","components"];return(e,t)=>{const s=n("BeButton");return i(),d("div",null,[o("h1",null,a(e.$frontmatter.title),1),o("p",null,a(e.$frontmatter.description),1),t[0]||(t[0]=v('<h2 id="문제" tabindex="-1" data-v-180be921>문제 <a class="header-anchor" href="#문제" aria-label="Permalink to &quot;문제&quot;" data-v-180be921>​</a></h2><ul data-v-180be921><li data-v-180be921>기존의 스타일과 기능이 결합된 SFC(single file component) 구조를 디자인 시스템 활용을 위해 스타일, 기능을 분리할 필요가 발생</li><li data-v-180be921>기존의 라이브러리는 프레임워크 의존이 강하기 때문에 다중 프레임워크 개발 환경에서 사용이 어려움</li></ul><h2 id="목표" tabindex="-1" data-v-180be921>목표 <a class="header-anchor" href="#목표" aria-label="Permalink to &quot;목표&quot;" data-v-180be921>​</a></h2><ul data-v-180be921><li data-v-180be921>디자인시스템을 적용하여 최소한의 디자인 토큰의 변화로 다양한 스타일 테마를 얻을 수 있도록 변경</li><li data-v-180be921>스타일과 기능의 완전한 분리로 독립된 스타일 프레임워크를 만들고 이는 이용해 다중 프레임워크 개발 환경에서 동일한 스타일 시스템을 사용하도록 함</li></ul><h2 id="frog-ui" tabindex="-1" data-v-180be921><img src="'+g+'" alt="frog-ui" width="18" data-v-180be921> Frog UI <a class="header-anchor" href="#frog-ui" aria-label="Permalink to &quot;![frog-ui](/img/frog-profile.svg){width=18} Frog UI&quot;" data-v-180be921>​</a></h2><div class="main-image" data-v-180be921><p data-v-180be921><a href="https://frog-ui-css.vercel.app/" target="_blank" rel="noreferrer" data-v-180be921><img src="'+f+'" alt="test" data-v-180be921></a></p></div><div class="caption" data-v-180be921>Frog UI document site main</div><h3 id="프로젝트-내용" tabindex="-1" data-v-180be921>프로젝트 내용 <a class="header-anchor" href="#프로젝트-내용" aria-label="Permalink to &quot;프로젝트 내용&quot;" data-v-180be921>​</a></h3><ul data-v-180be921><li data-v-180be921>디자인 토큰 기반의 스타일 구조로, 컬러·타이포·스페이싱 등 <strong data-v-180be921>기본 스타일 요소를 토큰으로 정의</strong>하고 이를 컴포넌트 스타일에 매핑.</li><li data-v-180be921>중복 정의를 줄이고 적은 수의 토큰 조합만으로 다양한 테마를 효율적으로 구성할 수 있게 설계.</li><li data-v-180be921>Vue/React 등 특정 프레임워크에 종속되지 않는 <strong data-v-180be921>독립적인 스타일 시스템</strong>으로 분리해, 별도의 빌드 시스템을 구축.</li><li data-v-180be921>컴포넌트 라이브러리에서 떼어낸 <strong data-v-180be921>경량 스타일 프레임워크</strong>로, 다양한 환경에서 재사용 가능한 디자인 시스템 기반 마련.</li></ul><h3 id="링크" tabindex="-1" data-v-180be921>링크 <a class="header-anchor" href="#링크" aria-label="Permalink to &quot;링크&quot;" data-v-180be921>​</a></h3><table tabindex="0" data-v-180be921><thead data-v-180be921><tr data-v-180be921><th data-v-180be921>Name</th><th data-v-180be921>URL</th></tr></thead><tbody data-v-180be921><tr data-v-180be921><td data-v-180be921>Demo</td><td data-v-180be921><a href="https://frog-ui-css.vercel.app/" target="_blank" rel="noreferrer" data-v-180be921>https://frog-ui-css.vercel.app/</a></td></tr><tr data-v-180be921><td data-v-180be921>Github</td><td data-v-180be921><a href="https://github.com/noistommy/frog-ui-css.git" target="_blank" rel="noreferrer" data-v-180be921>https://github.com/noistommy/frog-ui-css.git</a></td></tr></tbody></table><h2 id="beui-vue-headless-ui" tabindex="-1" data-v-180be921><img src="'+_+'" alt="be-ui" width="18" data-v-180be921> BEUI(vue) - Headless UI <a class="header-anchor" href="#beui-vue-headless-ui" aria-label="Permalink to &quot;![be-ui](/img/be-ui-vue.svg){width=18} BEUI(vue) - Headless UI&quot;" data-v-180be921>​</a></h2><div class="main-image" data-v-180be921><p data-v-180be921><a href="https://beui.vercel.app/" target="_blank" rel="noreferrer" data-v-180be921><img src="'+k+'" alt="test" data-v-180be921></a></p></div><div class="caption" data-v-180be921>BEUI(vue) document site main</div><h3 id="프로젝트-내용-1" tabindex="-1" data-v-180be921>프로젝트 내용 <a class="header-anchor" href="#프로젝트-내용-1" aria-label="Permalink to &quot;프로젝트 내용&quot;" data-v-180be921>​</a></h3><ul data-v-180be921><li data-v-180be921>Vue3 Composition API 기반의 공용 컴포넌트 라이브러리로, 스타일은 전부 외부 CSS 시스템(Frog UI)에 위임.</li><li data-v-180be921>컴포넌트는 props, slot, 상태 관리 등 기능 레이어만 제공하며, 실제 스타일 클래스는 디자인 시스템에서 공급받는 구조.</li><li data-v-180be921>기존 nt-ui-component 경험을 토대로, API 단순화·필수/선택 옵션 구분 등 사용성을 개선.</li><li data-v-180be921>스타일과 기능이 느슨하게 결합된 구조로, <strong data-v-180be921>브랜드별 테마 변경이나 리디자인</strong> 시 로직을 건드리지 않고 대응 가능.</li><li data-v-180be921>Vue 환경에서 디자인 시스템과 컴포넌트 아키텍처가 결합된 첫 버전의 플랫폼을 완성.</li></ul><h3 id="링크-1" tabindex="-1" data-v-180be921>링크 <a class="header-anchor" href="#링크-1" aria-label="Permalink to &quot;링크&quot;" data-v-180be921>​</a></h3><table tabindex="0" data-v-180be921><thead data-v-180be921><tr data-v-180be921><th data-v-180be921>Name</th><th data-v-180be921>URL</th></tr></thead><tbody data-v-180be921><tr data-v-180be921><td data-v-180be921>Demo</td><td data-v-180be921><a href="https://beui.vercel.app/" target="_blank" rel="noreferrer" data-v-180be921>https://beui.vercel.app/</a></td></tr><tr data-v-180be921><td data-v-180be921>Github</td><td data-v-180be921><a href="https://github.com/noistommy/beui" target="_blank" rel="noreferrer" data-v-180be921>https://github.com/noistommy/beui.git</a></td></tr><tr data-v-180be921><td data-v-180be921>NPM</td><td data-v-180be921><a href="https://www.npmjs.com/package/noist-beui" target="_blank" rel="noreferrer" data-v-180be921>https://www.npmjs.com/package/noist-beui</a></td></tr></tbody></table><h2 id="결과" tabindex="-1" data-v-180be921>결과 <a class="header-anchor" href="#결과" aria-label="Permalink to &quot;결과&quot;" data-v-180be921>​</a></h2><h2 id="keyword" tabindex="-1" data-v-180be921>Keyword <a class="header-anchor" href="#keyword" aria-label="Permalink to &quot;Keyword&quot;" data-v-180be921>​</a></h2>',20)),(i(),d(u,null,h(b,r=>c(s,{key:r,outline:"",round:"",compact:""},{default:m(()=>[p(a(r),1)]),_:2},1024)),64))])}}}),x=l(y,[["__scopeId","data-v-180be921"]]);export{I as __pageData,x as default};
